with feeds as (
    select HUB_PAYMENT_INSTRUMENT_HK, HUB_PAYMENT_INSTRUMENT_BK__CHEQUE_NO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_payment_instrument__hm_hcm_extract__9f47771524') }}
    union all
    select HUB_PAYMENT_INSTRUMENT_HK, HUB_PAYMENT_INSTRUMENT_BK__CHEQUE_NO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_payment_instrument__tpa_claim_details_ws__a7570b7de2') }}
)

select
    HUB_PAYMENT_INSTRUMENT_HK,
    BUSINESS_KEY,
    min(RECORD_SOURCE) as RECORD_SOURCE,
    min(SOURCE_RUN) as SOURCE_RUN,
    min(LOAD_DATETIME) as LOAD_DATETIME
